                            "type": "knob",
                            "param": "Pitch",
                            "label": "PITCH",
                            "style": "cream_fluted",
                            "scale": ["low", "mid", "high"],
                            "size": 58
                        },
                        {
                            "type": "knob",
                            "param": "Body",
                            "label": "BODY",
                            "style": "vintage_bakelite",
                            "scale": "0_to_10",
                            "size": 58
                        }
                    ]
                }
            ]
        }
    }
