                            "scale": ["low", "mid", "high"],
                            "size": 58
                        },
                        {
                            "type": "knob",
                            "param": "Head",
                            "label": "HEAD",
                            "style": "vintage_bakelite",
                            "scale": "0_to_10",
                            "size": 58
                        },
                        {
                            "type": "knob",
                            "param": "Wires",
                            "label": "WIRES",
                            "style": "anodized_knurled",
                            "scale": "1_to_6",
                            "size": 58
                        },
